def collect_merged_peft_params(module: FSDP) -> OrderedDict:
    """Collect full model weights with the active PEFT adapter temporarily merged.

    This is used by rollout backends that cannot load a PEFT type such as DoRA
    or AdaLoRA directly.  The merge is always undone before returning so the
    actor remains in its original trainable state.
    """

    peft_model = getattr(module, "_fsdp_wrapped_module", module)

    def _collect() -> OrderedDict:
        merged_params = OrderedDict()
        peft_model.merge_adapter()
        try:
            model = peft_model.base_model.model
            for name, param in model.state_dict().items():
                if "lora_" in name:
                    continue
                name = name.replace("_fsdp_wrapped_module.", "").replace(".base_layer", "")
                merged_params[name] = (
                    param.full_tensor().detach().cpu()
                    if hasattr(param, "full_tensor")
                    else param.detach().cpu()
                )
        finally:
            peft_model.unmerge_adapter()
        return merged_params

    if fsdp_version(module) > 0:
        with FSDP.summon_full_params(module, writeback=False):
            params = _collect()
        get_torch_device().empty_cache()
        return params
    return _collect()


